def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", {})
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit", 0) or 0

    # Network referral rule: self_employed applicants with requested_limit
    # above 4000 must go to manual review instead of being issued.
    employment = app.get("employment")
    requested_limit = app.get("requested_limit", 0) or 0
    if employment == "self_employed" and requested_limit > 4000:
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    else:  # manual_review or unknown
        return {"action": "queue_review", "limit": 0}
